  9	import com.fasterxml.jackson.databind.ObjectMapper;
 10	import com.fasterxml.jackson.databind.SerializationFeature;
 11	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
 12	import io.javalin.Javalin;
 13	import io.javalin.json.JavalinJackson;
 14	
 15	import java.sql.SQLException;
 16	
 17	public class Main {
 18	    public static void main(String[] args) {
 19	        // Configuração do banco de dados
 20	        String dbUrl = System.getenv().getOrDefault("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 21	        String dbUser = System.getenv().getOrDefault("DB_USER", "postgres");
 22	        String dbPassword = System.getenv().getOrDefault("DB_PASSWORD", "postgres");
 23	
 24	        DatabaseSetup database = new DatabaseSetup(dbUrl, dbUser, dbPassword);
 25	
 26	        try {
 27	            database.initialize();
 28	        } catch (SQLException e) {
 29	            System.err.println("Failed to initialize database: " + e.getMessage());
 30	            System.exit(1);
 31	        }
 32	
 33	        // Repositories
 34	        RoomRepository roomRepository = new RoomRepository(database);
 35	        ReservationRepository reservationRepository = new ReservationRepository(database);
 36	        MessageRepository messageRepository = new MessageRepository(database);
 37	
 38	        // Services
 39	        ReservationService reservationService = new ReservationService(
 40	            reservationRepository, roomRepository, messageRepository
 41	        );
 42	
 43	        // Controllers
 44	        RoomController roomController = new RoomController(roomRepository);
 45	        ReservationController reservationController = new ReservationController(
 46	            reservationService, reservationRepository, roomRepository
 47	        );
 48	        MessageController messageController = new MessageController(messageRepository);
 49	        ReportController reportController = new ReportController(reservationRepository);
 50	
 51	        // Configurar Jackson para JSON
 52	        ObjectMapper mapper = new ObjectMapper();
 53	        mapper.registerModule(new JavaTimeModule());
 54	        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 55	
 56	        // Configuração da porta
 57	        int port = Integer.parseInt(System.getenv().getOrDefault("PORT", "7070"));
 58	
 59	        // Criar aplicação Javalin
 60	        Javalin app = Javalin.create(config -> {
 61	            config.jsonMapper(new JavalinJackson(mapper, false));
 62	        }).start(port);
 63	
 64	        // Rotas
 65	        app.get("/rooms", roomController::list);
 66	
 67	        app.post("/reservations", reservationController::create);
 68	        app.get("/reservations/{id}", reservationController::get);
 69	        app.post("/reservations/{id}/confirmation", reservationController::confirm);
 70	        app.post("/reservations/{id}/cancellation", reservationController::cancel);
 71	        app.post("/reservations/{id}/check-in", reservationController::checkIn);
 72	        app.post("/reservations/{id}/check-out", reservationController::checkOut);
 73	        app.get("/reservations/{id}/document", reservationController::getDocument);
 74	
 75	        app.get("/messages", messageController::list);
 76	
 77	        app.get("/reports/occupancy", reportController::occupancy);
 78	        app.get("/reports/revenue", reportController::revenue);
 79	        app.get("/reports/tourism-tax", reportController::tourismTax);
 80	        app.get("/reports/rate-plans", reportController::ratePlans);
 81	
 82	        // Tratamento de exceções
 83	        app.exception(Exception.class, (e, ctx) -> {
 84	            e.printStackTrace();
 85	            ctx.status(500).json(java.util.Map.of(
 86	                "error", "INTERNAL_ERROR",
 87	                "message", "An internal error occurred"
 88	            ));
 89	        });
 90	
 91	        System.out.println("Pousada Maré Alta - Sistema de Reservas");
 92	        System.out.println("Servidor iniciado na porta " + port);
 93	    }
 94	}
