260	package br.com.pousadamarealta.api;
261	
262	import br.com.pousadamarealta.domain.reservation.*;
263	import br.com.pousadamarealta.domain.room.Room;
264	import br.com.pousadamarealta.domain.room.RoomRepository;
265	import io.javalin.http.Context;
266	
267	import java.sql.SQLException;
268	import java.time.LocalDate;
269	import java.time.format.DateTimeParseException;
270	import java.util.HashMap;
271	import java.util.Map;
272	
273	public class ReservationController {
274	    private final ReservationService reservationService;
275	    private final ReservationRepository reservationRepository;
276	    private final RoomRepository roomRepository;
277	
278	    public ReservationController(ReservationService reservationService,
279	                                ReservationRepository reservationRepository,
280	                                RoomRepository roomRepository) {
281	        this.reservationService = reservationService;
282	        this.reservationRepository = reservationRepository;
283	        this.roomRepository = roomRepository;
284	    }
285	
286	    public void create(Context ctx) throws SQLException {
287	        try {
288	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
289	
290	            String roomNumber = (String) body.get("roomNumber");
291	            String guestName = (String) body.get("guestName");
292	            String guestEmail = (String) body.get("guestEmail");
293	            String guestCpf = (String) body.get("guestCpf");
294	            String checkInStr = (String) body.get("checkIn");
295	            String checkOutStr = (String) body.get("checkOut");
296	            Integer guests = ((Number) body.get("guests")).intValue();
297	            String ratePlanStr = (String) body.get("ratePlan");
298	
299	            // Validações básicas
300	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
301	                checkInStr == null || checkOutStr == null || guests == null || ratePlanStr == null) {
302	                ctx.status(400).json(Map.of(
303	                    "error", "INVALID_REQUEST",
304	                    "message", "Missing required fields"
305	                ));
306	                return;
307	            }
308	
309	            if (guests < 1) {
310	                ctx.status(400).json(Map.of(
311	                    "error", "INVALID_REQUEST",
312	                    "message", "At least one guest is required"
313	                ));
314	                return;
315	            }
316	
317	            LocalDate checkIn = LocalDate.parse(checkInStr);
318	            LocalDate checkOut = LocalDate.parse(checkOutStr);
319	
320	            if (!checkOut.isAfter(checkIn)) {
321	                ctx.status(400).json(Map.of(
322	                    "error", "INVALID_REQUEST",
323	                    "message", "Check-out must be after check-in"
324	                ));
325	                return;
326	            }
327	
328	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
329	
330	            Reservation reservation = reservationService.create(
331	                roomNumber, guestName, guestEmail, guestCpf,
332	                checkIn, checkOut, guests, ratePlan
333	            );
334	
335	            ctx.status(201).json(toResponse(reservation));
336	
337	        } catch (DateTimeParseException e) {
338	            ctx.status(400).json(Map.of(
339	                "error", "INVALID_REQUEST",
340	                "message", "Invalid date format"
341	            ));
342	        } catch (IllegalArgumentException e) {
343	            if (e.getMessage().equals("Room not found")) {
344	                ctx.status(404).json(Map.of(
345	                    "error", "ROOM_NOT_FOUND",
346	                    "message", "Room not found"
347	                ));
348	            } else if (e.getMessage().equals("Capacity exceeded")) {
349	                ctx.status(422).json(Map.of(
350	                    "error", "CAPACITY_EXCEEDED",
351	                    "message", "Number of guests exceeds room capacity"
352	                ));
353	            } else if (e.getMessage().equals("Room unavailable")) {
354	                ctx.status(409).json(Map.of(
355	                    "error", "ROOM_UNAVAILABLE",
356	                    "message", "Room is not available for the selected dates"
357	                ));
358	            } else {
359	                throw e;
360	            }
361	        }
362	    }
363	
364	    public void get(Context ctx) throws SQLException {
365	        try {
366	            Long id = Long.parseLong(ctx.pathParam("id"));
367	            Reservation reservation = reservationRepository.findById(id)
368	                    .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
369	
370	            ctx.json(toResponse(reservation));
371	        } catch (IllegalArgumentException e) {
372	            ctx.status(404).json(Map.of(
373	                "error", "RESERVATION_NOT_FOUND",
374	                "message", "Reservation not found"
375	            ));
376	        }
377	    }
378	
379	    public void confirm(Context ctx) throws SQLException {
380	        try {
381	            Long id = Long.parseLong(ctx.pathParam("id"));
382	            Reservation reservation = reservationService.confirm(id);
383	            ctx.json(toResponse(reservation));
384	        } catch (IllegalArgumentException e) {
385	            ctx.status(404).json(Map.of(
386	                "error", "RESERVATION_NOT_FOUND",
387	                "message", "Reservation not found"
388	            ));
389	        } catch (IllegalStateException e) {
390	            ctx.status(409).json(Map.of(
391	                "error", "OPERATION_NOT_ALLOWED",
392	                "message", e.getMessage()
393	            ));
394	        }
395	    }
396	
397	    public void cancel(Context ctx) throws SQLException {
398	        try {
399	            Long id = Long.parseLong(ctx.pathParam("id"));
400	            Reservation reservation = reservationService.cancel(id);
401	            ctx.json(toResponse(reservation));
402	        } catch (IllegalArgumentException e) {
403	            ctx.status(404).json(Map.of(
404	                "error", "RESERVATION_NOT_FOUND",
405	                "message", "Reservation not found"
406	            ));
407	        } catch (IllegalStateException e) {
408	            ctx.status(409).json(Map.of(
409	                "error", "OPERATION_NOT_ALLOWED",
410	                "message", e.getMessage()
411	            ));
412	        }
413	    }
414	
415	    public void checkIn(Context ctx) throws SQLException {
416	        try {
417	            Long id = Long.parseLong(ctx.pathParam("id"));
418	            Reservation reservation = reservationService.checkIn(id);
419	            ctx.json(toResponse(reservation));
420	        } catch (IllegalArgumentException e) {
421	            ctx.status(404).json(Map.of(
422	                "error", "RESERVATION_NOT_FOUND",
423	                "message", "Reservation not found"
424	            ));
425	        } catch (IllegalStateException e) {
426	            ctx.status(409).json(Map.of(
427	                "error", "OPERATION_NOT_ALLOWED",
428	                "message", e.getMessage()
429	            ));
430	        }
431	    }
432	
433	    public void checkOut(Context ctx) throws SQLException {
434	        try {
435	            Long id = Long.parseLong(ctx.pathParam("id"));
436	            Reservation reservation = reservationService.checkOut(id);
437	            String document = reservationService.generateDocument(reservation);
438	            ctx.json(toDocumentResponse(reservation, document));
439	        } catch (IllegalArgumentException e) {
440	            ctx.status(404).json(Map.of(
441	                "error", "RESERVATION_NOT_FOUND",
442	                "message", "Reservation not found"
443	            ));
444	        } catch (IllegalStateException e) {
445	            ctx.status(409).json(Map.of(
446	                "error", "OPERATION_NOT_ALLOWED",
447	                "message", e.getMessage()
448	            ));
449	        }
450	    }
451	
452	    public void getDocument(Context ctx) throws SQLException {
453	        try {
454	            Long id = Long.parseLong(ctx.pathParam("id"));
455	            Reservation reservation = reservationRepository.findById(id)
456	                    .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
457	
458	            if (!reservation.isPaid()) {
459	                ctx.status(409).json(Map.of(
460	                    "error", "OPERATION_NOT_ALLOWED",
461	                    "message", "Document is only available for paid reservations"
462	                ));
463	                return;
464	            }
465	
466	            String document = reservationService.generateDocument(reservation);
467	            ctx.json(toDocumentResponse(reservation, document));
468	        } catch (IllegalArgumentException e) {
469	            ctx.status(404).json(Map.of(
470	                "error", "RESERVATION_NOT_FOUND",
471	                "message", "Reservation not found"
472	            ));
473	        }
474	    }
475	
476	    private Map<String, Object> toResponse(Reservation reservation) throws SQLException {
477	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
478	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
479	
480	        Map<String, Object> map = new HashMap<>();
481	        map.put("id", reservation.getId());
482	        map.put("roomNumber", reservation.getRoomNumber());
483	        map.put("guestName", reservation.getGuestName());
484	        map.put("guestEmail", reservation.getGuestEmail());
485	        map.put("guestCpf", reservation.getGuestCpf());
486	        map.put("checkIn", reservation.getCheckIn().toString());
487	        map.put("checkOut", reservation.getCheckOut().toString());
488	        map.put("guests", reservation.getGuests());
489	        map.put("ratePlan", reservation.getRatePlan().name());
490	        map.put("nights", reservation.getNights());
491	        map.put("subtotal", reservation.getSubtotal());
492	        map.put("discount", reservation.getDiscount());
493	        map.put("total", reservation.getTotal());
494	        map.put("status", reservation.getStatus().name());
495	        map.put("amountPaid", reservation.getAmountPaid());
496	        map.put("refund", reservation.getRefund());
497	        return map;
498	    }
499	
500	    private Map<String, Object> toDocumentResponse(Reservation reservation, String document) throws SQLException {
501	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
502	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
503	
504	        Map<String, Object> map = new HashMap<>();
505	        map.put("title", "Comprovante de reserva");
506	        map.put("reservationId", reservation.getId());
507	        map.put("guestName", reservation.getGuestName());
508	        map.put("guestCpf", reservation.getGuestCpf());
509	        map.put("roomNumber", reservation.getRoomNumber());
510	        map.put("roomType", room.getType().name());
511	        map.put("checkIn", reservation.getCheckIn().toString());
512	        map.put("checkOut", reservation.getCheckOut().toString());
513	        map.put("nights", reservation.getNights());
514	        map.put("subtotal", reservation.getSubtotal());
515	        map.put("discount", reservation.getDiscount());
516	        map.put("total", reservation.getTotal());
517	        return map;
518	    }
519	}
