286	    public void create(Context ctx) throws SQLException {
287	        try {
288	            Map<String, Object> body = ctx.bodyAsClass(Map.class);
289	
290	            String roomNumber = (String) body.get("roomNumber");
291	            String guestName = (String) body.get("guestName");
292	            String guestEmail = (String) body.get("guestEmail");
293	            String guestCpf = (String) body.get("guestCpf");
294	            String checkInStr = (String) body.get("checkIn");
295	            String checkOutStr = (String) body.get("checkOut");
296	            Integer guests = ((Number) body.get("guests")).intValue();
297	            String ratePlanStr = (String) body.get("ratePlan");
298	
299	            // Validações básicas
300	            if (roomNumber == null || guestName == null || guestEmail == null || guestCpf == null ||
301	                checkInStr == null || checkOutStr == null || guests == null || ratePlanStr == null) {
302	                ctx.status(400).json(Map.of(
303	                    "error", "INVALID_REQUEST",
304	                    "message", "Missing required fields"
305	                ));
306	                return;
307	            }
308	
309	            if (guests < 1) {
310	                ctx.status(400).json(Map.of(
311	                    "error", "INVALID_REQUEST",
312	                    "message", "At least one guest is required"
313	                ));
314	                return;
315	            }
316	
317	            LocalDate checkIn = LocalDate.parse(checkInStr);
318	            LocalDate checkOut = LocalDate.parse(checkOutStr);
319	
320	            if (!checkOut.isAfter(checkIn)) {
321	                ctx.status(400).json(Map.of(
322	                    "error", "INVALID_REQUEST",
323	                    "message", "Check-out must be after check-in"
324	                ));
325	                return;
326	            }
327	
328	            RatePlan ratePlan = RatePlan.valueOf(ratePlanStr);
329	
330	            Reservation reservation = reservationService.create(
331	                roomNumber, guestName, guestEmail, guestCpf,
332	                checkIn, checkOut, guests, ratePlan
333	            );
334	
335	            ctx.status(201).json(toResponse(reservation));
336	
337	        } catch (DateTimeParseException e) {
338	            ctx.status(400).json(Map.of(
339	                "error", "INVALID_REQUEST",
340	                "message", "Invalid date format"
341	            ));
342	        } catch (IllegalArgumentException e) {
343	            if (e.getMessage().equals("Room not found")) {
344	                ctx.status(404).json(Map.of(
345	                    "error", "ROOM_NOT_FOUND",
346	                    "message", "Room not found"
347	                ));
348	            } else if (e.getMessage().equals("Capacity exceeded")) {
349	                ctx.status(422).json(Map.of(
350	                    "error", "CAPACITY_EXCEEDED",
351	                    "message", "Number of guests exceeds room capacity"
352	                ));
353	            } else if (e.getMessage().equals("Room unavailable")) {
354	                ctx.status(409).json(Map.of(
355	                    "error", "ROOM_UNAVAILABLE",
356	                    "message", "Room is not available for the selected dates"
357	                ));
358	            } else {
359	                throw e;
360	            }
361	        }
