    12	public class PricingCalculator {
    13	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    14	
    15	    public static BigDecimal calculateNightlyRate(Room room, LocalDate date) {
    16	        BigDecimal baseRate = room.getNightlyRate();
    17	        if (DateUtils.isHighSeason(date)) {
    18	            return MoneyUtils.round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
    19	        }
    20	        return baseRate;
    21	    }
    22	
    23	    public static BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    24	        BigDecimal subtotal = BigDecimal.ZERO;
    25	        LocalDate current = checkIn;
    26	
    27	        while (current.isBefore(checkOut)) {
    28	            BigDecimal nightlyRate = calculateNightlyRate(room, current);
    29	            subtotal = subtotal.add(nightlyRate);
    30	            current = current.plusDays(1);
    31	        }
    32	
    33	        return MoneyUtils.round(subtotal);
    34	    }
    35	
    36	    public static BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    37	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate());
    38	        return MoneyUtils.round(discount);
    39	    }
    40	
    41	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    42	        return MoneyUtils.round(subtotal.subtract(discount));
    43	    }
    44	}
