    29	    public Reservation create(String roomNumber, String guestName, String guestEmail, String guestCpf,
    30	                             java.time.LocalDate checkIn, java.time.LocalDate checkOut,
    31	                             int guests, RatePlan ratePlan) throws SQLException {
    32	
    33	        // Validar quarto
    34	        Room room = roomRepository.findByNumber(roomNumber)
    35	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
    36	
    37	        // Validar capacidade
    38	        if (guests > room.getCapacity()) {
    39	            throw new IllegalArgumentException("Capacity exceeded");
    40	        }
    41	
    42	        // Validar disponibilidade
    43	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    44	            throw new IllegalArgumentException("Room unavailable");
    45	        }
    46	
    47	        // Calcular valores
    48	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    49	        BigDecimal subtotal = PricingCalculator.calculateSubtotal(room, checkIn, checkOut);
    50	        BigDecimal discount = PricingCalculator.calculateDiscount(subtotal, ratePlan);
    51	        BigDecimal total = PricingCalculator.calculateTotal(subtotal, discount);
    52	
    53	        // Criar reserva
    54	        Reservation reservation = new Reservation();
    55	        reservation.setRoomNumber(roomNumber);
    56	        reservation.setGuestName(guestName);
