   114	    private void sendConfirmationEmail(Reservation reservation) throws SQLException {
   115	        String document = generateDocument(reservation);
   116	
   117	        String body = String.format("""
   118	            Olá, %s!
   119	
   120	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
   121	
   122	            %s
   123	
   124	            A entrada é a partir das 14h, e a saída, até as 12h.
   125	            Até breve!
   126	            """, reservation.getGuestName(), document);
   127	
   128	        Message message = new Message();
   129	        message.setChannel(MessageChannel.EMAIL);
   130	        message.setTo(reservation.getGuestEmail());
   131	        message.setSubject("Reserva confirmada - Pousada Maré Alta");
   132	        message.setBody(body);
   133	
   134	        messageRepository.save(message);
   135	    }
   136	
   137	    public String generateDocument(Reservation reservation) throws SQLException {
   138	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
   139	                .orElseThrow(() -> new IllegalArgumentException("Room not found"));
   140	
   141	        String cpfFormatted = formatCpf(reservation.getGuestCpf());
   142	        String nightsLabel = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
   143	
   144	        StringBuilder sb = new StringBuilder();
   145	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
   146	        sb.append("Hóspede: ").append(reservation.getGuestName())
   147	          .append(" (CPF ").append(cpfFormatted).append(")\n");
   148	        sb.append("Quarto: ").append(reservation.getRoomNumber())
   149	          .append(" (").append(room.getType().name()).append(")\n");
   150	        sb.append("Entrada: ").append(DateUtils.formatDisplay(reservation.getCheckIn()))
   151	          .append(" | Saída: ").append(DateUtils.formatDisplay(reservation.getCheckOut()))
   152	          .append(" | ").append(nightsLabel).append("\n");
   153	        sb.append("Diárias: ").append(MoneyUtils.formatCurrency(reservation.getSubtotal())).append("\n");
   154	
   155	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
   156	            sb.append("Desconto: ").append(MoneyUtils.formatCurrency(reservation.getDiscount())).append("\n");
   157	        }
   158	
   159	        sb.append("Total: ").append(MoneyUtils.formatCurrency(reservation.getTotal()));
   160	
   161	        return sb.toString();
   162	    }
   163	
   164	    private String formatCpf(String cpf) {
   165	        // Remove tudo que não é número
   166	        String numbers = cpf.replaceAll("\\D", "");
   167	        // Formata: 111.222.333-44
   168	        return numbers.substring(0, 3) + "." +
   169	               numbers.substring(3, 6) + "." +
   170	               numbers.substring(6, 9) + "-" +
   171	               numbers.substring(9, 11);
   172	    }
   173	}
