    19	    public static boolean isHighSeason(LocalDate date) {
    20	        Month month = date.getMonth();
    21	        int day = date.getDayOfMonth();
    22	
    23	        // Julho inteiro
    24	        if (month == Month.JULY) {
    25	            return true;
    26	        }
    27	
    28	        // 15 de dezembro até fim de fevereiro
    29	        if (month == Month.DECEMBER && day >= 15) {
    30	            return true;
    31	        }
    32	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    33	            return true;
    34	        }
    35	
    36	        return false;
    37	    }
