    17	    private Map<RatePlan, List<Reservation>> reservationsByPlan;
    18	
    19	    public RatePlanReport(ReservationRepository reservationRepository, int year, int month) {
    20	        this.reservationRepository = reservationRepository;
    21	        this.year = year;
    22	        this.month = month;
    23	    }
