    37	        try {
    38	            List<Reservation> allReservations = reservationRepository.findByCheckInMonth(year, month);
    39	
    40	            reservationsByPlan = allReservations.stream()
    41	                    .filter(r -> r.getAmountKept().compareTo(BigDecimal.ZERO) > 0)
    42	                    .collect(Collectors.groupingBy(Reservation::getRatePlan));
    43	
